actions.script:
org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!org || org == '_NA_') org = null

def items = []
try { if (ec.context.itemsJson) items = new groovy.json.JsonSlurper().parseText(ec.context.itemsJson) } catch (e) { items = [] }
if (!items) { ec.message.addError('No items to send to the kitchen.'); return }

def kf = ec.entity.find('zenith.erp.pos.KitchenOrderTicket')
if (org) kf.condition('organizationPartyId', org)
def last = kf.orderBy('-kotDate').limit(1).list()
def nextNum = 1001
if (last) { try { nextNum = ((last[0].kotNumber ?: '1000') as Integer) + 1 } catch (e) { nextNum = 1001 } }

def notesVal = (ec.context.orderType ? ('[' + ec.context.orderType + '] ') : '') + (ec.context.notes ?: '')
def kr = ec.service.sync().name('create#zenith.erp.pos.KitchenOrderTicket')
    .parameters([organizationPartyId:org, kotNumber:String.valueOf(nextNum),
                 tableNumber:ec.context.tableNumber, statusId:'KotNew', printCount:0,
                 kotDate:ec.user.nowTimestamp, notes:notesVal]).call()
def newKotId = kr.kotId
def seq = 0
items.each { it2 ->
    seq++
    ec.service.sync().name('create#zenith.erp.pos.KotItem')
        .parameters([kotId:newKotId, kotItemSeqId:String.format('%05d', seq),
                     productId:it2.productId, productName:it2.productName,
                     quantity:((it2.quantity ?: 1) as BigDecimal),
                     specialInstructions:it2.specialInstructions]).call()
}
// if this order was resumed from a saved draft, remove the draft (it has become live)
def dId = ec.context.loadedDraftId
if (dId) {
    def d = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId', dId).one()
    if (d && d.statusId == 'KotDraft' && (!org || d.organizationPartyId == org)) {
        ec.entity.find('zenith.erp.pos.KotItem').condition('kotId', dId).deleteAll()
        d.delete()
    }
}
ec.message.addMessage('KOT #' + nextNum + ' sent to the kitchen.')

org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!org || org == '_NA_') org = null

def items = []
try { if (ec.context.itemsJson) items = new groovy.json.JsonSlurper().parseText(ec.context.itemsJson) } catch (e) { items = [] }
if (!items) { ec.message.addError('Add items before saving a draft.'); return }

// replacing a resumed draft => delete the old one first
def exId = ec.context.existingDraftId
if (exId) {
    def ex = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId', exId).one()
    if (ex && ex.statusId == 'KotDraft' && (!org || ex.organizationPartyId == org)) {
        ec.entity.find('zenith.erp.pos.KotItem').condition('kotId', exId).deleteAll()
        ex.delete()
    }
}

def kf = ec.entity.find('zenith.erp.pos.KitchenOrderTicket')
if (org) kf.condition('organizationPartyId', org)
def last = kf.orderBy('-kotDate').limit(1).list()
def nextNum = 1001
if (last) { try { nextNum = ((last[0].kotNumber ?: '1000') as Integer) + 1 } catch (e) { nextNum = 1001 } }

def notesVal = (ec.context.orderType ? ('[' + ec.context.orderType + '] ') : '') + (ec.context.notes ?: '')
def kr = ec.service.sync().name('create#zenith.erp.pos.KitchenOrderTicket')
    .parameters([organizationPartyId:org, kotNumber:String.valueOf(nextNum),
                 tableNumber:ec.context.tableNumber, statusId:'KotDraft', printCount:0,
                 kotDate:ec.user.nowTimestamp, notes:notesVal]).call()
def newKotId = kr.kotId
def seq = 0
items.each { it2 ->
    seq++
    ec.service.sync().name('create#zenith.erp.pos.KotItem')
        .parameters([kotId:newKotId, kotItemSeqId:String.format('%05d', seq),
                     productId:it2.productId, productName:it2.productName,
                     quantity:((it2.quantity ?: 1) as BigDecimal),
                     specialInstructions:it2.specialInstructions]).call()
}
ec.message.addMessage('Saved as Draft #' + nextNum + '.')

org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!org || org == '_NA_') org = null
def k = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId', ec.context.kotId).one()
if (k && k.statusId == 'KotDraft' && (!org || k.organizationPartyId == org)) {
    ec.entity.find('zenith.erp.pos.KotItem').condition('kotId', ec.context.kotId).deleteAll()
    k.delete()
}

import java.math.RoundingMode
import groovy.json.JsonOutput
org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!org || org == '_NA_') org = null

def inr = { amt ->
    def n = ((amt ?: 0) as BigDecimal).setScale(2, RoundingMode.HALF_UP)
    def neg = n.signum() < 0; n = n.abs()
    def intPart = n.toBigInteger().toString()
    def frac = n.remainder(BigDecimal.ONE).movePointRight(2).toBigInteger().toString().padLeft(2, '0')
    def res
    if (intPart.length() <= 3) { res = intPart }
    else {
        def last3 = intPart.substring(intPart.length() - 3)
        def rest = intPart.substring(0, intPart.length() - 3)
        def sb = new StringBuilder()
        while (rest.length() > 2) { sb.insert(0, ',' + rest.substring(rest.length() - 2)); rest = rest.substring(0, rest.length() - 2) }
        sb.insert(0, rest); res = sb.toString() + ',' + last3
    }
    return (neg ? '-' : '') + '₹' + res + '.' + frac
}

def cf = ec.entity.find('mantle.product.category.ProductCategory')
if (org) cf.condition('ownerPartyId', org)
categoryList = cf.orderBy('categoryName').limit(60).list()

def pf = ec.entity.find('mantle.product.Product').condition('productTypeEnumId', 'PtAsset')
if (org) pf.condition('ownerPartyId', org)
def products = pf.orderBy('productName').limit(300).list()

def IN = org.moqui.entity.EntityCondition.ComparisonOperator.IN
def prodCat = [:]
if (products) {
    def pids = products.collect { it.productId }
    def mems = ec.entity.find('mantle.product.category.ProductCategoryMember')
        .condition('productId', IN, pids)
        .conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp)
        .orderBy('sequenceNum,productCategoryId').list()
    mems.each { m -> if (!prodCat[m.productId]) prodCat[m.productId] = m.productCategoryId }
}
menuItems = products.collect { p ->
    def price = (p.mrpAmount ?: 0) as BigDecimal
    def nm = (p.productName ?: p.productId)
    [ id:p.productId, name:nm, price:price.setScale(2, RoundingMode.HALF_UP).toPlainString(),
      priceStr:inr(price), cat:(prodCat[p.productId] ?: ''),
      initial:(nm?.trim() ? nm.trim().substring(0, 1).toUpperCase() : 'X') ]
}

tables = ec.entity.find('zenith.erp.pos.RestaurantTable').orderBy('tableNumber').limit(200).list()

def kotLabel = { st ->
    if (st == 'KotNew') return 'Pending'
    if (st == 'KotPreparing') return 'In Kitchen'
    if (st == 'KotReady') return 'Ready'
    if (st == 'KotServed') return 'Served'
    if (st == 'KotCancelled') return 'Cancelled'
    if (st == 'KotDraft') return 'Draft'
    return st
}
def kotBadge = { st ->
    if (st == 'KotNew') return 'orange'
    if (st == 'KotPreparing' || st == 'KotReady') return 'green'
    return 'grey'
}
def loadKots = { statuses, lim ->
    def f = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('statusId', IN, statuses)
    if (org) f.condition('organizationPartyId', org)
    def ks = f.orderBy('-kotDate').limit(lim).list()
    if (!ks) return []
    def kids = ks.collect { it.kotId }
    def its = ec.entity.find('zenith.erp.pos.KotItem').condition('kotId', IN, kids).orderBy('kotId,kotItemSeqId').list()
    def byKot = [:]
    its.each { i ->
        def lst = byKot[i.kotId]; if (lst == null) { lst = []; byKot[i.kotId] = lst }
        lst.add([ name:(i.productName ?: i.productId), qty:(((i.quantity ?: 1) as BigDecimal).stripTrailingZeros().toPlainString()) ])
    }
    return ks.collect { k -> [ id:k.kotId, num:(k.kotNumber ?: k.kotId), table:(k.tableNumber ?: '-'),
        time:(k.kotDate ? ec.l10n.format(k.kotDate, 'hh:mm a') : ''),
        label:kotLabel(k.statusId), badge:kotBadge(k.statusId), items:(byKot[k.kotId] ?: []) ] }
}

activeKots = loadKots(['KotNew', 'KotPreparing', 'KotReady'], 60)
completedKots = loadKots(['KotServed', 'KotCancelled'], 60)
draftKots = loadKots(['KotDraft'], 30)
recentKots = activeKots.take(8)

// resume a draft into the cart?
loadedDraftId = ec.context.loadDraft ?: ''
def draftLoadItems = []
draftLoadTable = ''; draftLoadType = ''; draftLoadInstr = ''
if (loadedDraftId) {
    def dk = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('kotId', loadedDraftId).one()
    if (dk && dk.statusId == 'KotDraft' && (!org || dk.organizationPartyId == org)) {
        def dits = ec.entity.find('zenith.erp.pos.KotItem').condition('kotId', loadedDraftId).orderBy('kotItemSeqId').list()
        draftLoadItems = dits.collect { [ productId:it.productId, productName:it.productName,
            quantity:(((it.quantity ?: 1) as BigDecimal).stripTrailingZeros().toPlainString()) ] }
        draftLoadTable = dk.tableNumber ?: ''
        def nt = dk.notes ?: ''
        def mm = (nt =~ /^\[([^\]]*)\]\s?(.*)$/)
        if (mm.find()) { draftLoadType = mm.group(1); draftLoadInstr = mm.group(2) } else { draftLoadInstr = nt }
    } else { loadedDraftId = '' }
}

def printMap = [:]
(activeKots + completedKots + draftKots).each { k -> printMap[k.id] = [num:k.num, table:k.table, time:k.time, items:k.items] }
printOrdersJson = JsonOutput.toJson(printMap)
draftLoadJson = JsonOutput.toJson(draftLoadItems)
nowTime = ec.l10n.format(ec.user.nowTimestamp, 'hh:mm a')
